const sumTradingFeesFrom = `-- name: SumTradingFeesFrom :one
SELECT COALESCE(SUM(CASE WHEN ref_type = 'transaction_tax' THEN -amount ELSE 0 END), 0)::float8 AS sales_tax,
       COALESCE(SUM(CASE WHEN ref_type = 'brokers_fee' THEN -amount ELSE 0 END), 0)::float8 AS broker_fees
FROM ledger_journal
WHERE owner_kind = $1 AND owner_id = ANY($2::bigint[])
  AND at >= $3::timestamptz AND activity = 'trading'
`

type SumTradingFeesFromParams struct {
	OwnerKind string    `json:"owner_kind"`
	OwnerIds  []int64   `json:"owner_ids"`
	FromAt    time.Time `json:"from_at"`
}

type SumTradingFeesFromRow struct {
	SalesTax   float64 `json:"sales_tax"`
	BrokerFees float64 `json:"broker_fees"`
}

// Trading fees over the span, for the trading line's breakdown.
func (q *Queries) SumTradingFeesFrom(ctx context.Context, arg SumTradingFeesFromParams) (SumTradingFeesFromRow, error) {
	row := q.db.QueryRowContext(ctx, sumTradingFeesFrom, arg.OwnerKind, pq.Array(arg.OwnerIds), arg.FromAt)
	var i SumTradingFeesFromRow
	err := row.Scan(&i.SalesTax, &i.BrokerFees)
	return i, err
}

const upsertLedgerState = `-- name: UpsertLedgerState :exec
INSERT INTO ledger_state (owner_kind, owner_id, journal_at, txns_at, jobs_at, journal_hash, txns_hash, jobs_hash, folded_at)
VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
ON CONFLICT (owner_kind, owner_id) DO UPDATE SET
    journal_at = excluded.journal_at, txns_at = excluded.txns_at,
    jobs_at = excluded.jobs_at, journal_hash = excluded.journal_hash,
    txns_hash = excluded.txns_hash, jobs_hash = excluded.jobs_hash,
    folded_at = excluded.folded_at
`

type UpsertLedgerStateParams struct {
	OwnerKind   string       `json:"owner_kind"`
	OwnerID     int64        `json:"owner_id"`
	JournalAt   sql.NullTime `json:"journal_at"`
	TxnsAt      sql.NullTime `json:"txns_at"`
	JobsAt      sql.NullTime `json:"jobs_at"`
	JournalHash string       `json:"journal_hash"`
	TxnsHash    string       `json:"txns_hash"`
	JobsHash    string       `json:"jobs_hash"`
	FoldedAt    sql.NullTime `json:"folded_at"`
}

func (q *Queries) UpsertLedgerState(ctx context.Context, arg UpsertLedgerStateParams) error {
	_, err := q.db.ExecContext(ctx, upsertLedgerState,
		arg.OwnerKind,
		arg.OwnerID,
		arg.JournalAt,
		arg.TxnsAt,
		arg.JobsAt,
		arg.JournalHash,
		arg.TxnsHash,
		arg.JobsHash,
		arg.FoldedAt,
	)
	return err
}

